import React, { useState, useEffect } from 'react';
import { gameAPI } from '../services/api';
import '../styles/App.css';

const Games = () => {
  const [games, setGames] = useState([]);
  const [selectedGame, setSelectedGame] = useState(null);
  const [userScores, setUserScores] = useState([]);
  const [leaderboard, setLeaderboard] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showScores, setShowScores] = useState(false);
  const [memoryCards, setMemoryCards] = useState([]);
  const [flippedCards, setFlippedCards] = useState([]);
  const [matchedCards, setMatchedCards] = useState([]);
  const [gameStartTime, setGameStartTime] = useState(null);
  const [currentQuestion, setCurrentQuestion] = useState(0);
  const [userAnswers, setUserAnswers] = useState([]);
  const [gameScore, setGameScore] = useState(0);

  useEffect(() => {
    fetchGames();
    fetchUserScores();
  }, []);

  const fetchGames = async () => {
    try {
      const response = await gameAPI.getAllGames();
      setGames(response.data.games);
    } catch (error) {
      console.error('Error fetching games:', error);
    } finally {
      setLoading(false);
    }
  };

  const fetchUserScores = async () => {
    try {
      const response = await gameAPI.getUserScores();
      setUserScores(response.data.scores);
    } catch (error) {
      console.error('Error fetching scores:', error);
    }
  };

  const fetchLeaderboard = async (gameId) => {
    try {
      const response = await gameAPI.getLeaderboard(gameId, 10);
      setLeaderboard(response.data.leaderboard);
    } catch (error) {
      console.error('Error fetching leaderboard:', error);
    }
  };

  const playGame = async (game) => {
    setSelectedGame(game);
    fetchLeaderboard(game._id);
  };

  const submitScore = async (e) => {
    e.preventDefault();
    const score = Math.floor(Math.random() * 100);

    try {
      await gameAPI.submitScore({
        gameId: selectedGame._id,
        score,
        correctAnswers: Math.floor(score / 10),
        totalQuestions: 10,
        timeTaken: Math.floor(Math.random() * 3600),
      });
      alert(`Score submitted: ${score}/100`);
      fetchUserScores();
    } catch (error) {
      console.error('Error submitting score:', error);
    }
  };

  return (
    <div className="container">
      <h1>🎮 Games & Challenges</h1>

      {loading ? (
        <div className="spinner"></div>
      ) : (
        <div className="grid">
          {!selectedGame ? (
            <>
              {games.map((game) => (
                <div key={game._id} className="card">
                  <h3>{game.name}</h3>
                  <p>{game.description}</p>
                  <p>
                    <span className="badge badge-primary">{game.type}</span>
                    <span className="badge badge-warning" style={{ marginLeft: '0.5rem' }}>
                      {game.difficulty}
                    </span>
                  </p>
                  <p>Points: {game.totalPoints}</p>
                  <button onClick={() => playGame(game)} className="btn btn-primary">
                    Play Now
                  </button>
                </div>
              ))}
            </>
          ) : (
            <>
              <div className="card" style={{ gridColumn: '1 / -1' }}>
                <h2>{selectedGame.name}</h2>
                <p>{selectedGame.description}</p>

                <form onSubmit={submitScore}>
                  <div className="form-group">
                    <p>Answer the questions and submit your score!</p>
                    <button type="submit" className="btn btn-success">
                      Submit Score
                    </button>
                  </div>
                </form>

                <button
                  onClick={() => setSelectedGame(null)}
                  className="btn btn-danger"
                  style={{ marginTop: '1rem' }}
                >
                  Back to Games
                </button>
              </div>

              {/* Leaderboard */}
              <div className="card" style={{ gridColumn: '1 / -1' }}>
                <h3>Leaderboard</h3>
                <table>
                  <thead>
                    <tr>
                      <th>Rank</th>
                      <th>Player</th>
                      <th>Score</th>
                      <th>Correct Answers</th>
                    </tr>
                  </thead>
                  <tbody>
                    {leaderboard.map((entry, index) => (
                      <tr key={entry._id}>
                        <td>{index + 1}</td>
                        <td>{entry.userId?.name}</td>
                        <td>{entry.score}</td>
                        <td>{entry.correctAnswers}/{entry.totalQuestions}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </>
          )}
        </div>
      )}

      {/* Your Scores */}
      {!selectedGame && userScores.length > 0 && (
        <div style={{ marginTop: '2rem' }}>
          <h2>Your Recent Scores</h2>
          <table>
            <thead>
              <tr>
                <th>Game</th>
                <th>Score</th>
                <th>Correct Answers</th>
                <th>Time Taken</th>
              </tr>
            </thead>
            <tbody>
              {userScores.slice(0, 10).map((score) => (
                <tr key={score._id}>
                  <td>{score.gameId?.name}</td>
                  <td>{score.score}</td>
                  <td>{score.correctAnswers}/{score.totalQuestions}</td>
                  <td>{Math.floor(score.timeTaken / 60)}m {score.timeTaken % 60}s</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
};

export default Games;
